mapper.select:
SELECT id, user_id, idempotent_key, biz_type, file_hash, file_name, file_url,
       relative_path, file_size, content_type, file_ext, create_time
FROM file_upload_record
WHERE user_id = #{userId}
  AND biz_type = #{bizType}
  AND file_hash = #{fileHash}
  AND file_ext = #{fileExt}
LIMIT 1
